baseCss:
.aha-pricing{
  container:aha-pricing / inline-size;
  position:relative;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-pricing *{box-sizing:border-box}
.aha-pricing--accent{box-shadow:inset 0 0 0 100vmax var(--aha-bg-accent)}
.aha-pricing--accent .aha-pricing__table{background:var(--aha-white)}
:where(.aha-pricing) :is(h2,h3,p,ul,ol,figure,table){margin:0;padding:0}
:where(.aha-pricing) ul{list-style:none}
.aha-pricing__inner{--aha-web-gutter:var(--aha-space-64);max-width:1280px;margin:0 auto;padding:var(--aha-section-space-block) var(--aha-web-gutter)}
.aha-pricing__header{max-width:720px;margin:0 0 var(--aha-section-space-header)}
.aha-pricing__header--center{margin-inline:auto;text-align:center}
.aha-pricing__title{display:block;text-align:inherit;font-size:var(--aha-size-h2);line-height:var(--aha-line-height-heading);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-headlines);color:var(--aha-text-default)}
.aha-pricing__lead{max-width:44ch;margin-top:var(--aha-space-20);font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-pricing__header--center .aha-pricing__lead{margin-inline:auto}
.aha-pricing__sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-pricing__toggle-row{display:flex;justify-content:center;margin:0 0 var(--aha-section-space-group)}
.aha-pricing__toggle-row--start{justify-content:flex-start}
.aha-pricing__toggle{display:inline-flex;flex-wrap:wrap;align-items:center;gap:var(--aha-space-12)}
.aha-pricing__grid{display:grid;gap:var(--aha-section-space-item);align-items:stretch}
.aha-pricing__grid--3{grid-template-columns:repeat(3,minmax(0,1fr))}
.aha-pricing__grid--2{grid-template-columns:repeat(2,minmax(0,1fr))}
.aha-pricing__cell{position:relative;min-width:0}
.aha-pricing__split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:var(--aha-section-space-header);align-items:start}
.aha-pricing__split .aha-pricing__header{margin-bottom:var(--aha-section-space-group)}
.aha-pricing__items{display:flex;flex-direction:column;gap:var(--aha-section-space-item)}
.aha-pricing__item{display:flex;gap:var(--aha-space-16)}
.aha-pricing__item-icon{display:inline-flex;flex:none;align-items:center;justify-content:center;width:var(--aha-space-48);height:var(--aha-space-48);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-lg);background:var(--aha-white);color:var(--aha-icon-strong);box-shadow:0 var(--aha-space-2) var(--aha-space-4) var(--aha-ink-a10)}
.aha-pricing__item-title{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-pricing__item-text{margin-top:var(--aha-space-4);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-pricing__table-wrap{width:100%;border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-default)}
.aha-pricing__table{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed;text-align:center}
.aha-pricing__table caption{position:absolute}
.aha-pricing__plan-head{padding:var(--aha-space-24) var(--aha-space-16);background:var(--aha-white);vertical-align:top;font-weight:var(--aha-weight-regular)}
.aha-pricing__plan-head>*{display:block;margin-top:var(--aha-space-8)}
.aha-pricing__plan-head>:first-child{margin-top:0}
.aha-pricing__plan-head aha-tag{display:inline-flex;margin-left:var(--aha-space-8)}
.aha-pricing__plan-head>.aha-marketing-card__price{display:flex;justify-content:center}
.aha-pricing__plan-head .aha-marketing-card__text{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-tertiary)}
.aha-pricing__plan-actions{margin-top:var(--aha-space-16)}
.aha-pricing__group th{padding:var(--aha-space-24) var(--aha-space-16) var(--aha-space-8);text-align:left;font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-pricing__table tbody tr:not(.aha-pricing__group) :is(th,td){height:var(--aha-space-60);padding:0 var(--aha-space-16);border-top:1px solid var(--aha-border-default);font-size:var(--aha-size-default);color:var(--aha-text-secondary);vertical-align:middle}
.aha-pricing__table tbody tr:not(.aha-pricing__group) th{text-align:left;font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__table tbody tr:not(.aha-pricing__group):hover :is(th,td){background:var(--aha-gray-30)}
.aha-pricing__row-end{white-space:nowrap}
.aha-pricing__table th aha-tooltip{margin-left:var(--aha-space-4);vertical-align:middle}
.aha-pricing__table td aha-icon,.aha-pricing__stack td aha-icon{color:var(--aha-color-primary)}
.aha-pricing__table td aha-icon[name="system-minus"],.aha-pricing__stack td aha-icon[name="system-minus"]{color:var(--aha-icon-muted)}
.aha-pricing__foot-cell{padding:var(--aha-space-24) var(--aha-space-16);border-top:1px solid var(--aha-border-default)}
.aha-pricing__table .aha-pricing__col--featured{box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-pricing__table thead .aha-pricing__col--featured{border-radius:var(--aha-radius-default) var(--aha-radius-default) 0 0;box-shadow:inset var(--aha-space-2) var(--aha-space-2) 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-pricing__table .aha-pricing__col--last{border-radius:0 0 var(--aha-radius-default) var(--aha-radius-default);box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary),inset 0 calc(-1 * var(--aha-space-2)) 0 var(--aha-color-primary)}
.aha-pricing__stack{display:none}
.aha-pricing__stack-plan{display:flex;flex-direction:column;gap:var(--aha-space-24);padding:var(--aha-space-32) 0}
.aha-pricing__stack-head{display:flex;flex-direction:column;gap:var(--aha-space-12);text-align:left}
.aha-pricing__stack-head>.aha-marketing-card__price{display:flex}
.aha-pricing__stack-head .aha-marketing-card__text{color:var(--aha-text-secondary)}
.aha-pricing__stack-head aha-tag{align-self:flex-start}
.aha-pricing__stack-table{width:100%;border-collapse:collapse;text-align:left}
.aha-pricing__stack-caption{padding:var(--aha-space-8) 0;text-align:left;font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-pricing__stack-table thead th{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-pricing__stack-table tbody :is(th,td){height:var(--aha-space-60);padding:0 var(--aha-space-8);border-top:1px solid var(--aha-border-default);font-size:var(--aha-size-default);vertical-align:middle}
.aha-pricing__stack-table tbody th{font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__stack-table tbody td{text-align:right;color:var(--aha-text-secondary)}
.aha-pricing__slider{position:relative;display:flex;justify-content:space-between;padding-top:var(--aha-space-32);margin:0 0 var(--aha-section-space-group)}
.aha-pricing__slider-rail{position:absolute;top:var(--aha-space-8);left:0;right:0;height:var(--aha-space-4);border-radius:var(--aha-radius-pill);background:var(--aha-gray-30)}
.aha-pricing__slider-fill{position:absolute;top:0;bottom:0;border-radius:var(--aha-radius-pill);background:var(--aha-color-primary)}
.aha-pricing__slider-input{position:absolute;top:0;left:0;width:100%;height:var(--aha-space-16);margin:0;background:none;pointer-events:none;-webkit-appearance:none;appearance:none}
.aha-pricing__slider-input::-webkit-slider-thumb{-webkit-appearance:none;pointer-events:auto;width:var(--aha-space-16);height:var(--aha-space-16);border:var(--aha-space-2) solid var(--aha-color-primary);border-radius:var(--aha-radius-pill);background:var(--aha-white);cursor:pointer}
.aha-pricing__slider-input::-moz-range-thumb{pointer-events:auto;box-sizing:border-box;width:var(--aha-space-16);height:var(--aha-space-16);border:var(--aha-space-2) solid var(--aha-color-primary);border-radius:var(--aha-radius-pill);background:var(--aha-white);cursor:pointer}
.aha-pricing__slider-input:focus-visible::-webkit-slider-thumb{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-pricing__slider-input:focus-visible::-moz-range-thumb{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-pricing__slider-label{font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__switch{display:inline-flex;align-items:center;gap:var(--aha-space-12);margin:0 0 var(--aha-space-24)}
.aha-pricing__switch-label{font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__style-stage>.aha-pricing__toggle{margin:0 0 var(--aha-space-24)}
.aha-pricing__styles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--aha-section-space-item);align-items:start}
.aha-pricing__style{min-width:0}
.aha-pricing__style--wide{grid-column:span 2}
.aha-pricing__style-label{display:flex;flex-direction:column;gap:var(--aha-space-2);margin:0 0 var(--aha-space-12);font-size:var(--aha-size-default);color:var(--aha-text-default)}
.aha-pricing__style-label span{color:var(--aha-text-tertiary)}
.aha-pricing__style-stage{position:relative;isolation:isolate;padding:var(--aha-space-24);border-radius:var(--aha-radius-marketing)}
.aha-pricing__style-stage--callout{padding-top:var(--aha-space-48)}
.aha-pricing__style-stage--band-soft{background:var(--aha-vivid-pink-5)}
.aha-pricing__style-stage--band-soft::before{content:"";position:absolute;inset:0 0 50% 0;z-index:-1;border-radius:var(--aha-radius-marketing) var(--aha-radius-marketing) 0 0;background:var(--aha-vivid-pink-30)}
.aha-pricing__style-stage--band{background:var(--aha-color-primary)}
@container aha-pricing (max-width:991px){
  .aha-pricing__title{font-size:var(--aha-size-h3)}
  .aha-pricing__grid--3{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__split{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__styles{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-pricing__style--wide{grid-column:span 2}
}
@container aha-pricing (max-width:767px){
  .aha-pricing__inner{--aha-web-gutter:var(--aha-space-24)}
  .aha-pricing__grid--2{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__styles{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__style--wide{grid-column:auto}
  .aha-pricing__table-wrap{display:none}
  .aha-pricing__stack{display:block}
}
@container aha-pricing (max-width:479px){
  .aha-pricing__inner{--aha-web-gutter:var(--aha-space-16)}
  .aha-pricing__title{font-size:var(--aha-size-h4)}
}
